urls.rule:
var rule = {
    title: 'PPnix影视',
    host: 'https://www.ppnix.com',
    url: '/cn/fyclass/',
    searchable: 2,
    quickSearch: 0,
    filterable: 0,
    headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Referer': 'https://www.ppnix.com/'
    },
    class_name: '电影&电视剧',
    class_url: 'movie&tv',
    play_parse: true,
    lazy: $js => {
        let m3u8 = request(input);
        let keyUrl = 'https://www.ppnix.com/info/m3u8/key';
        m3u8 = m3u8.replace(/\.\.\/key/g, keyUrl);
        m3u8 = m3u8.replace(/https:\/\/ipfs\.ppnix\.com\/ipfs\//g, 'https://walkah.cloud/ipfs/');
        return {parse:1, url: m3u8};
    },
    一级: '.lists-content li;h2 a&&Text;img.thumb&&src;a&&href;footer span.rate&&Text',
    二级: {
        title: 'h1.product-title&&Text',
        img: 'img.thumb&&src',
        desc: '',
        content: '',
        tabs: 'js:TABS=["播放列表"]',
        lists: $js => {
            let html = request(input);
            let m = html.match(/classid=(\d+);classurl='([^']+?)';infoid=(\d+);sub='([^']*?)';m3u8=(\[.*?\])/);
            if (!m) { LISTS = [[]]; return; }
            let infoid = m[3];
            let qualities = eval(m[5]);
            let list = qualities.map(function(q, i) {
                return q + '$' + rule.host + '/info/m3u8/' + infoid + '/' + q + '.m3u8';
            });
            LISTS = [list];
        }
    },
    搜索: '.lists-content li;h2 a&&Text;img.thumb&&src;a&&href;footer span.rate&&Text'
};
